def valid(household):
    if not (isinstance(household, list) and 3 <= len(household) <= 1000):
        return False
    for h in household:
        if not (isinstance(h, list) and len(h) == 4 and all(type(x) is int for x in h)):
            return False
        num, has, kids, score = h
        if not (1 <= num <= 1000 and has in (0, 1) and 0 <= kids <= 10 and 1 <= score <= 100):
            return False
        if (has == 1) != (kids >= 1):
            return False
    return len(set(h[0] for h in household)) == len(household)

